"""압박 복구 schema 후보는 검토한 컬럼·CHECK·trigger helper만 바꾼다."""
from copy import deepcopy
import hashlib
import json

import pytest

from db import schema_contract as sc
from tests.test_schema_contract_dev_refresh import _CatalogConnection, DSN, REF


def baseline():
    # The artifact stays generated by the parent's real dev metadata check.
    return json.loads(sc.CONTRACT.read_text())["catalog"]


def test_guard_context_manifest_changes_only_reviewed_objects():
    before = baseline()
    after = sc.reviewed_guard_context_catalog_upgrade(before)
    assert before == baseline()  # no caller mutation
    for section in before:
        for key, value in before[section].items():
            assert after[section][key] == value
    assert after["columns"]["public.chat_contexts.retention_pressure_through_message_id"] == sc._column("bigint")
    assert len(after["functions"]) in {len(before["functions"]), len(before["functions"])+2}
    for name in sc._PRESSURE_FUNCTIONS:
        function = after["functions"][f"public.{name}()"]
        assert "SET search_path TO ''" in function["definition"]
        assert not any(key.startswith(f"public.{name}():") for key in after["function_grants"])
    assert sc.reviewed_guard_context_catalog_upgrade(after) == after


def test_manifest_rejects_conflicting_object_or_direct_execution_grant():
    before = deepcopy(baseline())
    before["columns"]["public.chat_contexts.retention_pressure_through_message_id"] = sc._column("text")
    with pytest.raises(ValueError, match="conflicting"):
        sc.reviewed_guard_context_catalog_upgrade(before)
    before = deepcopy(baseline())
    before["function_grants"]["public.reset_retention_pressure_privacy():PUBLIC:EXECUTE"] = {"grantable": False}
    with pytest.raises(ValueError, match="function grant"):
        sc.reviewed_guard_context_catalog_upgrade(before)


def test_candidate_schema_is_idempotent_and_contains_both_same_transaction_fences():
    source = sc.SCHEMA.read_text()
    assert sc.reviewed_guard_context_schema_upgrade(source) == source
    assert "BEFORE UPDATE OF memory_generation ON public.chat_contexts" in source
    assert "AFTER INSERT OR UPDATE OF state, epoch ON public.privacy_subject_barriers" in source
    assert "NEW.retention_pressure_through_message_id := NULL;" in source
    assert "WHERE user_id = NEW.user_id AND retention_pressure_through_message_id IS NOT NULL" in source
    sql = sc.REVIEWED_GUARD_CONTEXT_SQL.read_text()
    assert "DELETE FROM messages" not in sql and "UPDATE messages" not in sql


@pytest.mark.parametrize("unrelated_drift", [False, True])
async def test_guard_refresh_reads_actual_metadata_and_rejects_unrelated_function(monkeypatch, tmp_path, unrelated_drift):
    before = baseline()
    # A minimal reviewed source baseline is sufficient; the whole catalog is preserved.
    original = ('    contract_generation bigint DEFAULT 0 NOT NULL,\n'
        '-- FUNCTION: public.guard_normalized_memory_snapshot()\n'
        '-- TRIGGER: public.orders orders_set_updated_at\n'
        '-- ACL: public.FUNCTION guard_normalized_memory_snapshot()\n')
    source, previous, artifact, sql = (tmp_path / name for name in
        ('schema.sql', 'baseline.sql', 'contract.json', 'guard_context_v2.sql'))
    previous.write_text(original)
    source.write_text(sc.reviewed_guard_context_schema_upgrade(original))
    artifact.write_text(json.dumps({'schema_sha256': hashlib.sha256(previous.read_bytes()).hexdigest(),
                                    'catalog': before}))
    sql.write_bytes(sc.REVIEWED_GUARD_CONTEXT_SQL.read_bytes())
    original_artifact = artifact.read_bytes()
    actual = sc.reviewed_guard_context_catalog_upgrade(before)
    if unrelated_drift:
        actual['functions']['public.unrelated_helper(uuid)'] = {'owner': 'postgres', 'definition': 'unrelated'}
    connection = _CatalogConnection(actual)
    async def connect(*args, **kwargs):
        return connection
    monkeypatch.setattr(sc, 'SCHEMA', source)
    monkeypatch.setattr(sc, 'CONTRACT', artifact)
    monkeypatch.setattr(sc, 'REVIEWED_GUARD_CONTEXT_SQL', sql)
    monkeypatch.setattr(sc.asyncpg, 'connect', connect)
    problems = await sc.refresh_from_dev(DSN, env='dev', expected_project_ref=REF,
        reviewed_sql=sql, expected_sha256=hashlib.sha256(sql.read_bytes()).hexdigest(),
        baseline_schema=previous, strict=True)
    assert connection.closed and connection.transactions == [{'isolation': 'repeatable_read', 'readonly': True}]
    if unrelated_drift:
        assert problems == ['unexpected functions: public.unrelated_helper(uuid)']
        assert artifact.read_bytes() == original_artifact
    else:
        assert problems == []
        generated = json.loads(artifact.read_bytes())
        assert generated['catalog'] == actual
        assert generated['schema_sha256'] == hashlib.sha256(source.read_bytes()).hexdigest()
